/**
 * `nextly plugins install` and `uninstall`, and the state each records, on
 * every configured dialect, through the commands' entry points.
 *
 * Only the config is faked. The adapter is a real one over a throwaway
 * database, and the plugin's two modules are generated by the real generator,
 * so the install applies them through the phase `nextly migrate` uses. After
 * each command the test reads the tables, the ledger and the boot's gate:
 *
 * - an install, a full uninstall and a reinstall that reads and writes its
 *   table again;
 * - an uninstall keeping data, and a reinstall that finds the rows;
 * - a full uninstall stopped after its first committed drop, which the boot
 *   refuses until the uninstall is run again and finishes.
 */
import { sql } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { buildExtensionSchema } from "../../../domains/schema/extension/build-extension-schema";
import { col, defineTable } from "../../../domains/schema/extension/dsl";
import { SchemaEventsRepository } from "../../../domains/schema/events/schema-events-repository";
import { buildPluginMigration } from "../../../domains/schema/migrate-create/generate-plugin";
import { reconcileCore } from "../../../domains/schema/migrate/core-reconcile";
import type { PluginMigration } from "../../../domains/schema/migrate/plugin/plugin-migration";
import { assertBootPluginsInstalled } from "../../../domains/schema/ownership/plugin-install-gate";
import { SchemaOwnersRepository } from "../../../domains/schema/ownership/schema-owners-repository";
import { MYSQL_MIGRATE_LOCK_NAME } from "../../../domains/schema/pipeline/locks";
import {
  createTestNextly,
  getConfiguredTestDialects,
  type TestNextly,
} from "../../../plugins/test-nextly";
import { CORE_TABLE_NAMES } from "../../../schemas/index";
import type { CommandContext } from "../../program";
import { createLogger } from "../../utils/logger";
import {
  runPluginInstall,
  runPluginUninstall,
} from "../plugin-lifecycle-runner";

const ALL = ["postgresql", "mysql", "sqlite"] as const;
type Dialect = (typeof ALL)[number];

const run = vi.hoisted(() => ({
  dialect: "sqlite" as string,
  adapter: undefined as unknown as {
    dialect: string;
    transaction: (...args: never[]) => Promise<unknown>;
  },
  plugin: undefined as unknown,
  /** Runs after each adapter transaction commits, when set. */
  afterTransaction: undefined as (() => Promise<void>) | undefined,
}));

vi.mock("../../utils/config-loader", () => ({
  loadConfig: async () => {
    const config = {
      db: { migrationsDir: "./migrations" },
      plugins: [run.plugin],
    };
    return { config, appConfig: config, pluginConsent: undefined };
  },
}));

vi.mock("../../utils/adapter", () => ({
  validateDatabaseEnv: () => ({
    valid: true,
    dialect: run.dialect,
    databaseUrl: "unused",
  }),
  // The test's adapter, kept connected after the command so the test can
  // read the database, with a hook after each committed transaction.
  createCliAdapter: async () =>
    Object.assign(Object.create(run.adapter) as object, {
      disconnect: async () => {},
      transaction: async (...args: never[]) => {
        const result = await run.adapter.transaction(...args);
        await run.afterTransaction?.();
        return result;
      },
    }),
}));

const PLUGIN = "@acme/lc";
const context = {
  logger: createLogger({ quiet: true }),
} as unknown as CommandContext;

const notes = defineTable("notes", {
  id: col.id(),
  body: col.shortText({ nullable: true }),
});
const tags = defineTable("tags", {
  id: col.id(),
  label: col.shortText({ nullable: true }),
});

/** The plugin's tables compiled for every dialect by the real builder. */
async function tablesByDialect(tables: ReturnType<typeof defineTable>[]) {
  const out = {} as Parameters<
    typeof buildPluginMigration
  >[0]["tablesByDialect"];
  for (const dialect of ALL) {
    const built = await buildExtensionSchema({
      dialect,
      coreTableNames: CORE_TABLE_NAMES,
      entities: [],
      pluginPrefixes: new Map([[PLUGIN, "lc"]]),
      plugins: [{ owner: { kind: "plugin", id: PLUGIN }, tables }],
    });
    out[dialect] = built.specs;
  }
  return out;
}

/** Two modules: the first creates `lc__notes`, the second `lc__tags`. */
async function generateModules(): Promise<PluginMigration[]> {
  const first = buildPluginMigration({
    pluginName: PLUGIN,
    schemaVersion: 1,
    name: "notes",
    now: new Date(Date.UTC(2026, 9, 14, 10, 0, 0)),
    tablesByDialect: await tablesByDialect([notes]),
    existing: [],
  });
  if (!first) throw new Error("no first module generated");
  const second = buildPluginMigration({
    pluginName: PLUGIN,
    schemaVersion: 2,
    name: "tags",
    now: new Date(Date.UTC(2026, 9, 14, 11, 0, 0)),
    tablesByDialect: await tablesByDialect([notes, tags]),
    existing: [first.module],
  });
  if (!second) throw new Error("no second module generated");
  return [first.module, second.module];
}

let modules: PluginMigration[] = [];

describe.each(getConfiguredTestDialects())(
  "plugin install and uninstall states (%s)",
  dialect => {
    let handle: TestNextly;
    const db = () => handle.adapter.getDrizzle();

    beforeEach(async () => {
      if (modules.length === 0) modules = await generateModules();
      handle = await createTestNextly(dialect === "sqlite" ? {} : { dialect });
      await reconcileCore({
        db: db(),
        dialect,
        logger: { info: () => {}, warn: () => {} },
      });
      run.dialect = dialect;
      run.adapter = handle.adapter as unknown as typeof run.adapter;
      run.afterTransaction = undefined;
      run.plugin = {
        name: PLUGIN,
        version: "1.0.0",
        contributes: {
          schema: { prefix: "lc", tables: [notes, tags], migrations: modules },
        },
      };
    });

    afterEach(async () => {
      await handle?.destroy();
    });

    const install = () => runPluginInstall(PLUGIN, {}, context);
    const uninstall = (keepData: boolean) =>
      runPluginUninstall(PLUGIN, { keepData, yes: true }, context);

    /** The boot's gate over this database, as a production boot runs it. */
    const boot = () =>
      assertBootPluginsInstalled({
        plugins: [{ name: PLUGIN }],
        readLifecycleEvents: () =>
          new SchemaEventsRepository(db(), dialect).listPluginLifecycle(),
        ledgerExists: async () => true,
        readOwners: () => new SchemaOwnersRepository(db(), dialect).read(),
        registryExists: async () => true,
        production: true,
        warn: () => {},
      });

    const exists = (table: string) => handle.adapter.tableExists(table);

    /**
     * What a process that died leaves of its connections: none. MySQL's
     * migrate lock belongs to a connection, and a process that stops frees it
     * by closing it; one that throws and carries on, as this test's does, can
     * leave the lock with an idle pooled connection, so that connection is
     * closed here as the dying process's would be. PostgreSQL's lock is a
     * row the command's own error path removes, and SQLite holds none.
     */
    async function endStoppedProcess(): Promise<void> {
      if (dialect !== "mysql") return;
      const db = handle.adapter.getDrizzle<{
        execute: (q: unknown) => Promise<unknown>;
      }>();
      const result = await db.execute(
        sql`SELECT IS_USED_LOCK(${MYSQL_MIGRATE_LOCK_NAME}) AS holder`
      );
      // mysql2 answers [rows, fields].
      const [held] = (
        Array.isArray(result) && Array.isArray(result[0]) ? result[0] : result
      ) as Array<{
        holder: number | null;
      }>;
      if (held?.holder) {
        await handle.adapter.executeQuery(`KILL ${String(held.holder)}`);
      }
    }

    const q = (name: string) =>
      dialect === "mysql" ? `\`${name}\`` : `"${name}"`;

    async function writeNote(id: string): Promise<void> {
      await handle.adapter.executeQuery(
        `INSERT INTO ${q("lc__notes")} (${q("id")}, ${q("body")}) VALUES ('${id}', 'kept')`
      );
    }

    async function noteIds(): Promise<string[]> {
      const rows = (await handle.adapter.executeQuery(
        `SELECT ${q("id")} AS id FROM ${q("lc__notes")}`
      )) as Array<{ id: string }>;
      return rows.map(row => row.id);
    }

    it("is refused at a production boot until the install command has run", async () => {
      await expect(boot()).rejects.toMatchObject({
        code: "PLUGIN_NOT_INSTALLED",
      });

      await install();

      expect(await exists("lc__notes")).toBe(true);
      expect(await exists("lc__tags")).toBe(true);
      await expect(boot()).resolves.toBeUndefined();
    });

    it("drops its tables on a full uninstall, refuses the boot, and reinstalls to tables it reads and writes", async () => {
      await install();
      await writeNote("before");

      await uninstall(false);

      expect(await exists("lc__notes")).toBe(false);
      expect(await exists("lc__tags")).toBe(false);
      await expect(boot()).rejects.toMatchObject({
        code: "PLUGIN_SCHEMA_UNINSTALLED",
      });

      await install();

      expect(await exists("lc__tags")).toBe(true);
      await writeNote("after");
      expect(await noteIds()).toEqual(["after"]);
      await expect(boot()).resolves.toBeUndefined();
    });

    it("keeps its tables and rows on an uninstall keeping data, refuses the boot, and reinstalls over them", async () => {
      await install();
      await writeNote("kept");

      await uninstall(true);

      expect(await noteIds()).toEqual(["kept"]);
      await expect(boot()).rejects.toMatchObject({
        code: "PLUGIN_SCHEMA_UNINSTALLED",
      });

      await install();

      expect(await noteIds()).toEqual(["kept"]);
      await expect(boot()).resolves.toBeUndefined();
    });

    it("refuses the boot after an uninstall stopped at its first committed drop, and finishes when run again", async () => {
      await install();
      // Stands in for the process dying once the newest module's DOWN has
      // committed: `lc__tags` is gone, `lc__notes` is still there.
      run.afterTransaction = async () => {
        if (await exists("lc__tags")) return;
        run.afterTransaction = undefined;
        throw new Error("process stopped");
      };

      await expect(uninstall(false)).rejects.toThrow("process stopped");
      await endStoppedProcess();

      expect(await exists("lc__tags")).toBe(false);
      expect(await exists("lc__notes")).toBe(true);
      await expect(boot()).rejects.toMatchObject({
        code: "PLUGIN_UNINSTALL_UNFINISHED",
      });

      // The other way round is refused; the way it began finishes it.
      await expect(uninstall(true)).rejects.toMatchObject({
        code: "PLUGIN_UNINSTALL_UNFINISHED",
      });
      await uninstall(false);

      expect(await exists("lc__notes")).toBe(false);
      await expect(boot()).rejects.toMatchObject({
        code: "PLUGIN_SCHEMA_UNINSTALLED",
      });
    });
  }
);
